/* Generated by scripts/split-content.mjs / merge-additions.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"Project Charter","def":"Document formally authorizing the project. Names the project manager, defines objectives, and grants authority to use organizational resources.","cat":"Management","sub":"PMP"},{"id":"c001","term":"Stakeholder Register","def":"Document identifying all stakeholders, their interests, influence, and engagement level. Updated throughout the project.","cat":"Management","sub":"PMP"},{"id":"c002","term":"WBS (Work Breakdown Structure)","def":"Hierarchical decomposition of the total scope into manageable work packages. The foundation of scope, schedule, and cost planning.","cat":"Management","sub":"PMP"},{"id":"c003","term":"Critical Path Method","def":"Identifies the longest sequence of dependent tasks determining the minimum project duration. Any delay on the critical path delays the project.","cat":"Management","sub":"PMP"},{"id":"c004","term":"Earned Value Management","def":"Integrates scope, schedule, and cost to measure project performance. Key metrics: PV (planned), EV (earned), AC (actual), SPI, CPI.","cat":"Management","sub":"PMP"},{"id":"c005","term":"SPI / CPI","def":"Schedule Performance Index (EV/PV): >1 is ahead. Cost Performance Index (EV/AC): >1 is under budget. Both measure efficiency.","cat":"Management","sub":"PMP"},{"id":"c006","term":"RACI Matrix","def":"Responsible, Accountable, Consulted, Informed. Clarifies who does what for each deliverable or activity.","cat":"Management","sub":"PMP"},{"id":"c007","term":"Risk Register","def":"Log of identified risks with probability, impact, response strategy, and owner. Living document updated throughout the project.","cat":"Management","sub":"PMP"},{"id":"c008","term":"Risk Response Strategies","def":"Negative: avoid, transfer, mitigate, accept. Positive: exploit, share, enhance, accept. Each risk gets a planned response.","cat":"Management","sub":"PMP"},{"id":"c009","term":"Change Control Board (CCB)","def":"Group responsible for reviewing and approving or rejecting change requests. Ensures changes go through a formal process.","cat":"Management","sub":"PMP"},{"id":"c010","term":"Scope Creep","def":"Uncontrolled expansion of project scope without corresponding adjustments to time, cost, or resources. Prevented by change control.","cat":"Management","sub":"PMP"},{"id":"c011","term":"Predictive vs. Adaptive","def":"Predictive (waterfall): plan-driven, sequential phases. Adaptive (agile): iterative, incremental delivery. Hybrid combines both.","cat":"Management","sub":"PMP"},{"id":"c012","term":"Lessons Learned","def":"Knowledge gained during a project that is documented and shared to improve future projects. Captured throughout, not only at closing.","cat":"Management","sub":"PMP"},{"id":"c013","term":"Procurement Types","def":"Fixed-price (seller bears cost risk), cost-reimbursable (buyer bears cost risk), time-and-materials (hybrid). Selection depends on scope certainty.","cat":"Management","sub":"PMP"},{"id":"c014","term":"TOGAF","def":"The Open Group Architecture Framework. A methodology and set of tools for developing enterprise architecture through the Architecture Development Method.","cat":"Management","sub":"TOGAF"},{"id":"c015","term":"ADM (Architecture Development Method)","def":"TOGAF's core process: Preliminary, Architecture Vision, Business Architecture, IS Architecture, Technology Architecture, Opportunities, Migration Planning, Governance, Change Management.","cat":"Management","sub":"TOGAF"},{"id":"c016","term":"Architecture Repository","def":"Central store of architectural assets: standards, reference models, landscape descriptions, and governance records.","cat":"Management","sub":"TOGAF"},{"id":"c017","term":"Enterprise Continuum","def":"Classification scheme for architecture assets from generic (Foundation Architecture) to specific (Organization-Specific Architecture).","cat":"Management","sub":"TOGAF"},{"id":"c018","term":"Architecture Building Blocks (ABB)","def":"Technology-agnostic functional specifications. Describe what is needed without dictating how it is implemented.","cat":"Management","sub":"TOGAF"},{"id":"c019","term":"Solution Building Blocks (SBB)","def":"Technology-specific components that implement ABBs. Represent actual products, services, or custom solutions.","cat":"Management","sub":"TOGAF"},{"id":"c020","term":"Stakeholder Management in TOGAF","def":"Identifying stakeholders, understanding their concerns, and creating views and viewpoints that address those concerns.","cat":"Management","sub":"TOGAF"},{"id":"c021","term":"Architecture Governance","def":"Practice of managing and controlling architecture at an enterprise level. Ensures compliance with principles, standards, and reference architectures.","cat":"Management","sub":"TOGAF"},{"id":"c022","term":"Scrum Framework","def":"Iterative framework with fixed-length Sprints (1–4 weeks). Three roles: Product Owner, Scrum Master, Developers. Three artifacts: Product Backlog, Sprint Backlog, Increment.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c023","term":"Product Owner","def":"Responsible for maximizing the value of the product by managing the Product Backlog. Single point of accountability for what to build.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c024","term":"Scrum Master","def":"Serves the team by facilitating Scrum events, removing impediments, and coaching on Scrum practices. Not a project manager.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c025","term":"Sprint","def":"Time-boxed iteration (usually 2 weeks) producing a potentially shippable Increment. Scope is negotiable; duration is not.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c026","term":"Sprint Planning","def":"Event where the team selects Product Backlog items for the Sprint and creates a plan to deliver them. Results in the Sprint Backlog.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c027","term":"Daily Scrum / Standup","def":"15-minute daily event for the developers to inspect progress and adapt the plan for the next 24 hours.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c028","term":"Sprint Review","def":"Event at the end of the Sprint where the team demonstrates the Increment to stakeholders and collects feedback.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c029","term":"Sprint Retrospective","def":"Event where the team inspects how the Sprint went and identifies improvements for the next Sprint.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c030","term":"Definition of Done","def":"Shared standard describing when an Increment is complete: coded, tested, documented, reviewed, and deployable.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c031","term":"Product Backlog Refinement","def":"Ongoing activity of adding detail, estimates, and order to Product Backlog items. Keeps the backlog ready for Sprint Planning.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c032","term":"Velocity","def":"Measure of work completed per Sprint, typically in story points. Used for forecasting, not comparison between teams.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c033","term":"User Story","def":"Short description of a feature from the user's perspective: As a [role], I want [capability] so that [benefit]. Includes acceptance criteria.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c034","term":"SAFe (Scaled Agile Framework)","def":"Framework for scaling Agile across large enterprises. Organizes teams into Agile Release Trains (ARTs) aligned to value streams.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c035","term":"Agile Release Train (ART)","def":"SAFe construct: a long-lived team of agile teams (50–125 people) that plans, commits, and executes together in Program Increments.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c036","term":"PI Planning","def":"SAFe's big-room planning event. All ART members align on a shared mission, identify dependencies, and commit to PI objectives for the next 8–12 weeks.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c037","term":"Kanban Board","def":"Visual workflow management tool. Columns represent stages; cards represent work items. WIP limits prevent overload and expose bottlenecks.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c038","term":"WIP Limits","def":"Maximum number of items allowed in a workflow stage. Constraining work in progress improves flow, reduces cycle time, and surfaces problems.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c039","term":"Continuous Integration / Continuous Delivery","def":"CI: merging and testing code frequently. CD: automating deployment so every change is release-ready. Together they accelerate feedback loops.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c040","term":"Project Management Plan","def":"The integrated document describing how the project will be executed, monitored, and closed. Contains subsidiary plans for each knowledge area plus the baselines. Formally approved, and changed only through change control.","cat":"Management","sub":"PMP"},{"id":"c041","term":"Scope Baseline","def":"The approved combination of scope statement, WBS, and WBS dictionary. Serves as the reference against which scope performance is measured and against which change requests are evaluated.","cat":"Management","sub":"PMP"},{"id":"c042","term":"Performance Measurement Baseline","def":"The integrated scope, schedule, and cost baselines used as the comparison point for earned value analysis. Includes contingency reserve but excludes management reserve.","cat":"Management","sub":"PMP"},{"id":"c043","term":"WBS Dictionary","def":"Document providing detail for each work package: description of work, assumptions, responsible organization, schedule milestones, resources, cost estimates, and acceptance criteria. Prevents ambiguity in the WBS itself.","cat":"Management","sub":"PMP"},{"id":"c044","term":"Requirements Traceability Matrix","def":"Grid linking each requirement to its origin, its associated deliverable, and its verification method. Ensures every requirement is delivered and tested, and that no unrequested work has been introduced.","cat":"Management","sub":"PMP"},{"id":"c045","term":"Assumption Log","def":"Record of assumptions and constraints identified throughout the project. Assumptions that prove false typically become risks or issues, so the log is reviewed rather than written once and filed.","cat":"Management","sub":"PMP"},{"id":"c046","term":"Issue Log","def":"Record of current problems requiring action, with owner and target resolution date. An issue is something that has already occurred; a risk is something that may occur. The two are tracked separately.","cat":"Management","sub":"PMP"},{"id":"c047","term":"Milestone","def":"A significant point or event in the project with zero duration and no resources. Used for reporting, gate approval, and contractual checkpoints rather than for describing work.","cat":"Management","sub":"PMP"},{"id":"c048","term":"Precedence Diagramming Method","def":"Technique for building a schedule network using four dependency types: Finish-to-Start (most common), Start-to-Start, Finish-to-Finish, and Start-to-Finish (rare). Nodes represent activities; arrows represent dependencies.","cat":"Management","sub":"PMP"},{"id":"c049","term":"Lead and Lag","def":"Lead accelerates a successor activity, allowing it to start before its predecessor finishes. Lag delays a successor by a specified period. Both modify a dependency relationship rather than changing activity duration.","cat":"Management","sub":"PMP"},{"id":"c050","term":"Schedule Compression","def":"Two techniques for shortening the schedule without reducing scope. Crashing adds resources to critical path activities, increasing cost. Fast tracking overlaps activities normally done in sequence, increasing risk and rework.","cat":"Management","sub":"PMP"},{"id":"c051","term":"Three-Point Estimating","def":"Estimate derived from optimistic, most likely, and pessimistic values. Triangular distribution averages the three equally. Beta or PERT distribution weights the most likely value four times: (O + 4M + P) / 6.","cat":"Management","sub":"PMP"},{"id":"c052","term":"Analogous vs. Parametric Estimating","def":"Analogous uses actual values from a similar past project — fast, less accurate, used early. Parametric applies a statistical relationship between variables, such as cost per square foot — more accurate when the underlying data is reliable.","cat":"Management","sub":"PMP"},{"id":"c053","term":"Contingency vs. Management Reserve","def":"Contingency reserve covers identified risks and sits inside the cost baseline, controlled by the project manager. Management reserve covers unknown-unknowns, sits outside the baseline, and requires management approval to access.","cat":"Management","sub":"PMP"},{"id":"c054","term":"Variance and Index Formulas","def":"SV = EV − PV and CV = EV − AC, both negative when unfavorable. SPI = EV / PV and CPI = EV / AC, both below 1 when unfavorable. Variances are absolute amounts; indices are efficiency ratios.","cat":"Management","sub":"PMP"},{"id":"c055","term":"EAC / ETC / TCPI","def":"Estimate at Completion forecasts total cost; the common formula when current variances are expected to continue is EAC = BAC / CPI. Estimate to Complete is the remaining forecast cost, EAC − AC. To-Complete Performance Index is the efficiency required to finish on budget: (BAC − EV) / (BAC − AC).","cat":"Management","sub":"PMP"},{"id":"c056","term":"Preliminary Phase","def":"Prepares the organization for architecture work. Defines the architecture framework to be used, tailors it to the enterprise, establishes governance structures, and defines architecture principles.","cat":"Management","sub":"TOGAF"},{"id":"c057","term":"Phase A — Architecture Vision","def":"Establishes scope, constraints, and expectations. Produces the Statement of Architecture Work and a high-level vision of the target architecture, secures sponsor approval, and identifies stakeholders and their concerns.","cat":"Management","sub":"TOGAF"},{"id":"c058","term":"Statement of Architecture Work","def":"Deliverable that defines the scope, approach, deliverables, schedule, and resources for the architecture engagement. Signed by the sponsor, it functions as the contract authorizing the work.","cat":"Management","sub":"TOGAF"},{"id":"c059","term":"Phase B — Business Architecture","def":"Describes the baseline and target business architecture: organization structure, business functions, processes, services, and information flows. Provides the justification for the architectures that follow.","cat":"Management","sub":"TOGAF"},{"id":"c060","term":"Phase C — Information Systems Architectures","def":"Covers both Data Architecture and Application Architecture. Describes the major data entities and the applications that process them, without specifying implementation technology.","cat":"Management","sub":"TOGAF"},{"id":"c061","term":"Phase D — Technology Architecture","def":"Defines the hardware, software, and network infrastructure required to support the application and data architectures. Maps logical components to physical technology.","cat":"Management","sub":"TOGAF"},{"id":"c062","term":"Gap Analysis","def":"Technique used in each architecture phase to compare the baseline against the target and identify what must be created, changed, or retired. The gaps become the input to Phase E work packages.","cat":"Management","sub":"TOGAF"},{"id":"c063","term":"Architecture Definition Document vs. Architecture Requirements Specification","def":"The Definition Document describes the architecture qualitatively across business, data, application, and technology domains. The Requirements Specification states the quantitative, measurable requirements the implementation must meet.","cat":"Management","sub":"TOGAF"},{"id":"c064","term":"Sprint Goal","def":"The single objective for the Sprint, agreed at Sprint Planning. Provides coherence and flexibility: if the work needed to meet the goal changes, the team adapts the Sprint Backlog while the goal itself stays fixed.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c065","term":"Increment","def":"A concrete, usable step toward the Product Goal. Every Increment is additive to prior ones and must meet the Definition of Done. Multiple Increments may be created within a single Sprint.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c066","term":"Product Goal","def":"The long-term objective the Scrum Team works toward, described in the Product Backlog. The team must fulfill or abandon one Product Goal before taking on the next.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c067","term":"Acceptance Criteria","def":"Conditions specific to a single backlog item that determine whether it does what was asked. Distinct from the Definition of Done, which is a universal quality standard applying to every item.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c068","term":"Story Points","def":"Unitless measure of relative size combining complexity, effort, and uncertainty. Deliberately not hours, so that estimates remain comparable across people and resist being read as commitments about time.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c069","term":"Relative Estimation","def":"Sizing items by comparison against a known reference item rather than by absolute duration. Humans compare more reliably than they predict, which is why the approach tends to be more stable than hour-based estimating.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c070","term":"Planning Poker","def":"Consensus estimating technique where team members reveal estimates simultaneously to avoid anchoring. Wide divergence signals differing understanding of the item, and the resulting discussion is the primary value.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c071","term":"Burndown Chart","def":"Plots remaining work against time within a Sprint. A flat line means no work is being completed; a line rising means scope was added. Useful for in-Sprint inspection, not for reporting to management as a performance metric.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c072","term":"Burnup Chart","def":"Plots completed work and total scope as two separate lines. Because scope is shown explicitly, a burnup distinguishes a team working slowly from a team absorbing added scope — a distinction a burndown hides.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c073","term":"Cumulative Flow Diagram","def":"Stacked area chart showing item counts in each workflow state over time. A widening band indicates a bottleneck at that stage; consistent band widths indicate stable flow.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c074","term":"Cycle Time / Lead Time","def":"Cycle time measures from when work starts to when it is delivered. Lead time measures from when the request arrives to when it is delivered, so it includes queue time. Customers experience lead time.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c075","term":"Throughput","def":"Number of items completed per unit of time. Unlike velocity it requires no estimation, which makes it usable for forecasting even on teams that have stopped sizing items.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c076","term":"Little's Law","def":"Average cycle time equals average work in progress divided by average throughput. The practical implication is that reducing WIP shortens cycle time without any change in team capacity.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c077","term":"Technical Debt","def":"Future cost incurred by choosing an expedient implementation over a better one. Deliberate debt taken knowingly can be sound; accidental debt from neglected quality compounds and slows delivery.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c078","term":"Spike","def":"Time-boxed research or prototyping item used to reduce uncertainty before a feature can be reliably estimated. Produces knowledge rather than shippable functionality, and the time box is what keeps it from expanding.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c079","term":"Epic / Feature / Story","def":"Hierarchy of backlog granularity. Epics are large bodies of work spanning releases, features deliver value within a release and fit a Program Increment, and stories are small enough to complete within a single Sprint.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c080","term":"Stakeholder Engagement Assessment Matrix","def":"Grid comparing each stakeholder's current engagement level (unaware, resistant, neutral, supportive, leading) against the desired level. The gap between C and D drives the engagement actions in the plan.","cat":"Management","sub":"PMP"},{"id":"c081","term":"Power/Interest Grid","def":"Classification of stakeholders by authority and concern. High power and high interest are managed closely; high power and low interest are kept satisfied; low power and high interest are kept informed; low on both are monitored. The salience model extends this with urgency and legitimacy.","cat":"Management","sub":"PMP"},{"id":"c082","term":"Communications Management Plan","def":"Defines what information is communicated, to whom, when, in what format, and by whom. Also records escalation paths and the glossary of terms. Most project problems reported as coordination failures trace back to a gap in this plan.","cat":"Management","sub":"PMP"},{"id":"c083","term":"Communication Channels Formula","def":"The number of potential communication paths in a group of n people is n(n − 1) / 2. Growth is quadratic, which is the structural argument for small teams and for defined communication protocols on large ones.","cat":"Management","sub":"PMP"},{"id":"c084","term":"Resource Breakdown Structure","def":"Hierarchical listing of resources by category and type — labor, material, equipment, supplies. Used for planning, acquisition, and reporting, and distinct from the organizational breakdown structure, which arranges work by department.","cat":"Management","sub":"PMP"},{"id":"c085","term":"Resource Leveling vs. Resource Smoothing","def":"Leveling adjusts start and finish dates to respect resource constraints and can extend the critical path. Smoothing adjusts activities only within their available float, so the critical path and project end date are preserved but resource peaks may remain.","cat":"Management","sub":"PMP"},{"id":"c086","term":"Tuckman Ladder","def":"Model of team development: forming (polite, uncertain), storming (conflict over approach), norming (agreement on working methods), performing (effective interdependent work), adjourning (release). Teams can regress when membership changes.","cat":"Management","sub":"PMP"},{"id":"c087","term":"Conflict Resolution Approaches","def":"Collaborate/problem solve (addresses the underlying issue, generally best), compromise (partial satisfaction for both), smooth/accommodate (emphasizes agreement, defers the issue), force/direct (win-lose, fastest, damages relationships), withdraw/avoid (defers entirely, appropriate only when the issue is trivial or emotions are too high).","cat":"Management","sub":"PMP"},{"id":"c088","term":"Servant Leadership","def":"Leadership style focused on removing impediments, developing team members, and enabling self-organization rather than directing tasks. Central to adaptive approaches, where authority over the work sits with the team.","cat":"Management","sub":"PMP"},{"id":"c089","term":"Quality Assurance vs. Quality Control","def":"Assurance is process-focused and preventive — auditing whether the right processes are being followed. Control is product-focused and inspective — measuring whether deliverables meet requirements. Assurance improves the process; control catches the defect.","cat":"Management","sub":"PMP"},{"id":"c090","term":"Cost of Quality","def":"Total cost of conformance (prevention and appraisal) plus cost of nonconformance (internal and external failure). Investment in prevention is consistently cheaper than external failure, which carries rework, warranty, and reputational cost.","cat":"Management","sub":"PMP"},{"id":"c091","term":"Control Chart","def":"Plots a process measurement over time against a mean and upper and lower control limits. Points outside the limits indicate an out-of-control process. The rule of seven states that seven consecutive points on one side of the mean signal a non-random trend even when all points remain within limits.","cat":"Management","sub":"PMP"},{"id":"c092","term":"Make-or-Buy Analysis","def":"Evaluation of whether to produce a deliverable internally or procure it. Considers cost, capacity, core competency, intellectual property, and risk. The output feeds procurement planning and the choice of contract type.","cat":"Management","sub":"PMP"},{"id":"c093","term":"Procurement Documents","def":"Request for Information gathers market intelligence. Request for Quotation seeks pricing on a well-defined item. Request for Proposal seeks a solution approach when the requirement is less defined and evaluation weighs method as well as price.","cat":"Management","sub":"PMP"},{"id":"c094","term":"PMI Code of Ethics and Professional Conduct","def":"Built on four values: responsibility, respect, fairness, and honesty. Requires disclosure of conflicts of interest, refusal of improper payments, accurate reporting of status, and respect for local laws and customs.","cat":"Management","sub":"PMP"},{"id":"c095","term":"Phase E — Opportunities and Solutions","def":"First phase focused on implementation. Consolidates gaps from Phases B through D into work packages, identifies major implementation projects, and determines whether an incremental approach requiring Transition Architectures is needed.","cat":"Management","sub":"TOGAF"},{"id":"c096","term":"Phase F — Migration Planning","def":"Produces the Implementation and Migration Plan. Prioritizes projects by business value and cost, confirms resource availability, and finalizes the Architecture Roadmap and Transition Architectures.","cat":"Management","sub":"TOGAF"},{"id":"c097","term":"Phase G — Implementation Governance","def":"Provides architectural oversight during implementation. Establishes the Architecture Contract with implementation teams, conducts compliance reviews, and issues dispensations where deviation is justified and time-bounded.","cat":"Management","sub":"TOGAF"},{"id":"c098","term":"Phase H — Architecture Change Management","def":"Establishes procedures for managing change to the new architecture. Determines whether a change is handled by simplification, incremental adjustment, or a full re-entry into the ADM cycle at Phase A.","cat":"Management","sub":"TOGAF"},{"id":"c099","term":"Requirements Management","def":"The central process of the ADM, connected to every phase rather than sequenced among them. Manages the flow of architecture requirements into and out of each phase; it does not dispose of requirements, which are handled within the phases themselves.","cat":"Management","sub":"TOGAF"},{"id":"c100","term":"Architecture Contract","def":"Joint agreement between development partners and sponsors on deliverables, quality, and fitness-for-purpose. Signed in Phase G, it makes architectural compliance enforceable during implementation.","cat":"Management","sub":"TOGAF"},{"id":"c101","term":"Architecture Content Metamodel","def":"Defines the formal structure of architectural artifacts and their relationships — actors, business services, data entities, application components, technology components. Provides consistency so that artifacts from different engagements can be compared and reused.","cat":"Management","sub":"TOGAF"},{"id":"c102","term":"Views and Viewpoints","def":"A viewpoint is the specification of how to construct a view — the conventions, notation, and concerns addressed. A view is the resulting representation of the system from that perspective. Viewpoints are selected to address identified stakeholder concerns.","cat":"Management","sub":"TOGAF"},{"id":"c103","term":"Transition Architecture","def":"An intermediate, deployable state between baseline and target, providing measurable business value along the way. Used when a single-step move to the target architecture is impractical.","cat":"Management","sub":"TOGAF"},{"id":"c104","term":"Value Stream","def":"The sequence of steps used to deliver value to a customer. Operational value streams deliver to the end customer; development value streams build the systems that enable them. SAFe organizes Agile Release Trains around value streams rather than functional departments.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c105","term":"Agile Release Train Roles","def":"The Release Train Engineer facilitates ART events and removes impediments across teams — a servant leader at program level. Product Management owns the program backlog and defines features. The System Architect provides technical guidance and defines enabler work.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c106","term":"Business Owners","def":"Small group of stakeholders with primary business and technical responsibility for an ART's outcomes. They assign business value to PI Objectives and participate in PI Planning and Inspect and Adapt.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c107","term":"PI Objectives","def":"Business summaries of what each team intends to deliver in the Program Increment. Business Owners assign business value from 1 to 10. Uncommitted objectives are included in planning but excluded from the commitment, providing capacity for variability.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c108","term":"Program Board","def":"Visual artifact from PI Planning showing feature delivery dates, cross-team dependencies, and milestones across the PI. Making dependencies visible in the room is the primary mechanism by which PI Planning reduces later delay.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c109","term":"Innovation and Planning Iteration","def":"Dedicated iteration at the end of each PI providing time for innovation, exploration, infrastructure work, continuing education, PI Planning, and Inspect and Adapt. It also acts as an estimating buffer that protects PI commitments.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c110","term":"Inspect and Adapt","def":"Event at the end of each PI comprising a system demo, quantitative and qualitative measurement, and a structured problem-solving workshop. Improvement items produced enter the next PI's backlog rather than being logged and forgotten.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c111","term":"ART Sync","def":"Regular coordination across the train, combining the Scrum of Scrums for delivery progress and dependency management with the PO Sync for scope and priority adjustments. Frequency is typically weekly or more often.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c112","term":"System Demo","def":"Demonstration of the integrated work of all teams on the train, held at the end of every iteration. It is the only true measure of ART progress, since individual team demos can hide integration failures.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c113","term":"Lean Portfolio Management","def":"Aligns strategy and execution by applying lean approaches to strategy and investment funding, agile portfolio operations, and governance. Funds value streams rather than projects, removing the overhead of per-project budgeting cycles.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c114","term":"Portfolio Epic","def":"A significant initiative requiring a lean business case and approval by Lean Portfolio Management before implementation. Tracked through a portfolio kanban with WIP limits, and defined with a minimum viable product to test the hypothesis before full funding.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c115","term":"Weighted Shortest Job First","def":"Prioritization model dividing Cost of Delay by job size. Cost of Delay is the sum of user-business value, time criticality, and risk reduction or opportunity enablement. The highest ratio is sequenced first, which maximizes economic benefit under a capacity constraint.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c116","term":"Cost of Delay","def":"The economic cost of not having something now. Combining it with duration is what makes sequencing decisions economic rather than political, and it is the numerator in WSJF.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c117","term":"Built-In Quality","def":"Practice of embedding quality into every increment rather than inspecting it in later. Includes continuous integration, test-first development, pairing, refactoring, and definition of done applied at team, program, and solution levels.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c118","term":"Continuous Delivery Pipeline","def":"Four elements: Continuous Exploration (understanding what to build), Continuous Integration (building and validating), Continuous Deployment (moving to production), and Release on Demand (making value available when the business chooses). Deployment and release are deliberately decoupled.","cat":"Management","sub":"Scrum/SAFe"},{"id":"c119","term":"Enabler","def":"Backlog item supporting future business functionality: exploration, architecture, infrastructure, or compliance work. Enablers are made visible in the backlog and given capacity allocation so that technical work competes transparently with features rather than hiding inside them.","cat":"Management","sub":"Scrum/SAFe"}],"questions":[{"cat":"Management","sub":"PMP","stem":"The document that formally authorizes a project and names the project manager is:","choices":["The WBS","The scope statement","The project charter","The RACI matrix"],"answer":2,"label":"Project charter","why":"The charter establishes the project, defines objectives, and grants the project manager authority to use resources.","id":"q001","n":1},{"cat":"Management","sub":"Scrum/SAFe","stem":"In Scrum, who is responsible for maximizing the value of the product?","choices":["The development team","The Product Owner","The stakeholders","The Scrum Master"],"answer":1,"label":"Product Owner role","why":"The Product Owner manages the Product Backlog and makes priority decisions to maximize value delivered.","id":"q008","n":8},{"cat":"Management","sub":"TOGAF","stem":"The ADM in TOGAF stands for:","choices":["Agile Development Methodology","Application Design Model","Automated Deployment Manager","Architecture Development Method"],"answer":3,"label":"ADM definition","why":"ADM is TOGAF's iterative process for developing and managing enterprise architecture through defined phases.","id":"q016","n":16},{"cat":"Management","sub":"PMP","stem":"If a project's CPI is 0.85, this means:","choices":["The project has 85% of scope remaining","The project is under budget","The project is 15% over budget for the work completed","The project is ahead of schedule"],"answer":2,"label":"CPI interpretation","why":"CPI < 1 means the project is getting less value per dollar spent than planned — 85 cents of value for every dollar.","id":"q002","n":2},{"cat":"Management","sub":"Scrum/SAFe","stem":"Sprint duration in Scrum is:","choices":["Changed at each Sprint Retrospective","Fixed and consistent throughout the project","Set by management","Variable based on the amount of work"],"answer":1,"label":"Fixed Sprint duration","why":"Sprint length is time-boxed and does not change. Scope within the Sprint is negotiable, but duration is not.","id":"q009","n":9},{"cat":"Management","sub":"TOGAF","stem":"Architecture Building Blocks differ from Solution Building Blocks in that ABBs are:","choices":["Only used for network architecture","Created after deployment","Technology-agnostic functional specifications","Technology-specific implementations"],"answer":2,"label":"ABB vs. SBB","why":"ABBs define what is needed functionally. SBBs define how it is implemented with specific technologies and products.","id":"q017","n":17},{"cat":"Management","sub":"PMP","stem":"The critical path in a project schedule is significant because:","choices":["Any delay on it directly delays the project finish date","It contains the easiest tasks","It can be ignored if the team is experienced","It always contains the most expensive tasks"],"answer":0,"label":"Critical path significance","why":"The critical path is the longest sequence of dependent activities. It determines the minimum project duration.","id":"q003","n":3},{"cat":"Management","sub":"Scrum/SAFe","stem":"The Sprint Retrospective focuses on:","choices":["Demonstrating the Increment to stakeholders","Planning the next Sprint's work","Reviewing the Product Backlog","Inspecting the team's process and identifying improvements"],"answer":3,"label":"Retrospective purpose","why":"The Retro inspects how the Sprint went regarding people, relationships, process, and tools, and plans improvements.","id":"q010","n":10},{"cat":"Management","sub":"TOGAF","stem":"The Enterprise Continuum in TOGAF classifies assets from:","choices":["Oldest to newest","Most generic (Foundation) to most specific (Organization-Specific)","Least expensive to most expensive","Smallest to largest"],"answer":1,"label":"Enterprise Continuum","why":"The continuum ranges from universal foundation architectures to organization-specific solutions, providing context for reuse.","id":"q018","n":18},{"cat":"Management","sub":"PMP","stem":"Scope creep is best prevented by:","choices":["A formal change control process","Allowing the team to make scope decisions independently","Over-estimating the initial scope","Adding buffer time to every task"],"answer":0,"label":"Preventing scope creep","why":"Change control requires formal evaluation and approval of scope changes, preventing uncontrolled expansion.","id":"q004","n":4}],"meta":{"total":90,"free":10,"split":true}};
